template <class Engine, class Shape, class Stride>
CUTE_HOST_DEVICE constexpr
LayoutType
layout_type(Tensor<Engine, Layout<Shape,Stride>> const&)
{
  static_assert(is_same<uint128_t, typename Engine::value_type>::value,
                "Expected uint128_t type in LayoutType conversion.");

  using Swizzle = get_swizzle_t<Engine>;
  constexpr int B = Swizzle::num_bits;
  constexpr int M = Swizzle::num_base;
  constexpr int S = Swizzle::num_shft;

140	
141	  static_assert(M == 4,           "Unsupported layout swizzle");
142	  static_assert(0 <= B && B <= 3, "Unsupported layout swizzle");
143	  static_assert(S == 3,           "Unsupported layout swizzle");
144	
145	  switch (B) {
146	    case 0: return LayoutType::INTERLEAVE;
147	    case 1: return LayoutType::B32;
148	    case 2: return LayoutType::B64;
149	    case 3: return LayoutType::B128;
150	  }
151	  return LayoutType::INTERLEAVE;  // ERROR
152	}
